-- Synthetic operational records only. All mutations and notifications roll back.
begin;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',label;end if;end$$;
create function pg_temp.denied(q text) returns void language plpgsql as $$begin begin execute q;exception when insufficient_privilege or check_violation or raise_exception or serialization_failure or not_null_violation then return;end;raise exception 'UNEXPECTEDLY ALLOWED: %',q;end$$;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values
('d1000000-0000-4000-8000-000000000001','owner@operations.invalid',now(),'{}'),
('d1000000-0000-4000-8000-000000000002','staff@operations.invalid',now(),'{}'),
('d1000000-0000-4000-8000-000000000003','supplier@operations.invalid',now(),'{}'),
('d1000000-0000-4000-8000-000000000004','buyer@operations.invalid',now(),'{}'),
('d1000000-0000-4000-8000-000000000005','other@operations.invalid',now(),'{}');
update public.user_roles set role=case user_id when 'd1000000-0000-4000-8000-000000000001' then 'super_admin' when 'd1000000-0000-4000-8000-000000000002' then 'admin' else 'supplier' end where user_id in('d1000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000002','d1000000-0000-4000-8000-000000000003','d1000000-0000-4000-8000-000000000005');
insert into public.businesses(id,owner_id,name,division,district) values('d2000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000003','Synthetic operations supplier','Dhaka','Dhaka'),('d2000000-0000-4000-8000-000000000002','d1000000-0000-4000-8000-000000000005','Synthetic other supplier','Dhaka','Dhaka');
insert into public.verification_applications(id,business_id,revision,status,valid_until) values('d3000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001',1,'approved',(now() at time zone 'Asia/Dhaka')::date+7),('d3000000-0000-4000-8000-000000000002','d2000000-0000-4000-8000-000000000002',1,'expired',(now() at time zone 'Asia/Dhaka')::date-1);
update public.businesses set verification_application_id=case id when 'd2000000-0000-4000-8000-000000000001' then 'd3000000-0000-4000-8000-000000000001'::uuid else 'd3000000-0000-4000-8000-000000000002'::uuid end where id in('d2000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000002');
create temp table fixture(w uuid,n uuid);grant all on fixture to authenticated;
set local request.jwt.claims='{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated"}';set local role authenticated;
select pg_temp.ok(public.admin_supplier_workspace('d2000000-0000-4000-8000-000000000001')->>'email'='supplier@operations.invalid','explicit safe email available to owner');
select pg_temp.ok((public.admin_supplier_operations_list('suppliers','{"q":"supplier@operations.invalid"}')->>'total')::int=1,'server email search');
select pg_temp.denied($$select public.admin_supplier_operations_list('suppliers','{}',1,101)$$);
select pg_temp.denied($$select public.admin_supplier_labels('d2000000-0000-4000-8000-000000000001',0,array['x'])$$);
select pg_temp.ok(public.admin_supplier_labels('d2000000-0000-4000-8000-000000000001',0,array[' Priority ','priority','Dhaka'])->'labels' @> '["Dhaka"]'::jsonb,'labels normalized and deduplicated');
select pg_temp.denied($$select public.admin_supplier_labels('d2000000-0000-4000-8000-000000000001',0,array['stale'])$$);
select pg_temp.ok((public.admin_supplier_operations_list('suppliers','{"label":"PRIORITY"}')->>'total')::int=1,'case insensitive label search');
insert into fixture(n) values(public.admin_supplier_note('d2000000-0000-4000-8000-000000000001','Private synthetic note body'));
select public.admin_supplier_archive_note(n,'Duplicate operational context') from fixture;
select pg_temp.ok((public.admin_supplier_operations_list('notes','{"business_id":"d2000000-0000-4000-8000-000000000001"}')->'rows'->0->>'archived_at') is not null,'note archive preserves history');
select pg_temp.denied($$select public.admin_supplier_issue_warning('d2000000-0000-4000-8000-000000000001','{}')$$);
select pg_temp.denied(format('select public.admin_supplier_issue_warning(%L,%L)','d2000000-0000-4000-8000-000000000001',jsonb_build_object('title','Correct listings','message','Synthetic warning content','corrective_action','Correct the product specifications','severity','warning','due_on',(now() at time zone 'Asia/Dhaka')::date-1)::text));
update fixture set w=public.admin_supplier_issue_warning('d2000000-0000-4000-8000-000000000001',jsonb_build_object('title','Correct listings','message','Synthetic warning content','corrective_action','Correct the product specifications','severity','warning','due_on',(now() at time zone 'Asia/Dhaka')::date));
select pg_temp.ok((public.admin_supplier_workspace('d2000000-0000-4000-8000-000000000001')->>'overdue_warnings')::int=0,'due date inclusive until Bangladesh midnight');
select pg_temp.denied(format('select public.admin_supplier_warning_decide(%L,0,''resolved'',''Stale review attempt'')',w)) from fixture;
select pg_temp.ok((public.admin_supplier_operations_list('renewals','{"q":"Synthetic","days":"7"}')->'rows'->0->>'id')='d2000000-0000-4000-8000-000000000002','expired first and upcoming inclusive');
select public.admin_supplier_renewal_reminder('d2000000-0000-4000-8000-000000000001');
select pg_temp.denied($$select public.admin_supplier_renewal_reminder('d2000000-0000-4000-8000-000000000001')$$);
reset role;
-- A pending replacement is already in the review queue; do not nag the supplier.
insert into public.verification_applications(business_id,revision,status) values('d2000000-0000-4000-8000-000000000002',2,'submitted');
set local role authenticated;
select pg_temp.denied($$select public.admin_supplier_renewal_reminder('d2000000-0000-4000-8000-000000000002')$$);
select pg_temp.ok((public.admin_supplier_operations_list('renewals','{"q":"Synthetic","days":"30"}')->>'total')::int=2,'30 day window includes expired and pending replacements');
select pg_temp.ok((public.admin_supplier_operations_list('renewals','{"q":"Synthetic","days":"60"}')->>'total')::int=2,'60 day window supported');
select pg_temp.denied($$select public.admin_supplier_operations_list('renewals','{"days":"90"}')$$);
reset role;
update public.supplier_warnings set due_on=(now() at time zone 'Asia/Dhaka')::date-1 where id=(select w from fixture);
select pg_temp.ok((select status='active' from public.account_statuses where user_id='d1000000-0000-4000-8000-000000000003'),'overdue deadline does not auto-suspend');
update public.account_statuses set status='suspended',reason='Synthetic suspension' where user_id='d1000000-0000-4000-8000-000000000003';
set local role authenticated;set local request.jwt.claims='{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated"}';
select pg_temp.ok((select count(*)=0 from public.supplier_internal_notes),'supplier notes RLS');
select pg_temp.ok((select count(*)=0 from public.supplier_management_records),'supplier labels RLS');
select pg_temp.ok((public.supplier_action_list()->>'total')::int=1 and (public.supplier_action_list()->'rows'->0->>'overdue')::boolean,'supplier gets own overdue warning');
select public.supplier_warning_respond(w,1,'Synthetic supplier corrected the listing') from fixture;
select pg_temp.denied(format('select public.supplier_warning_respond(%L,1,''Stale response attempt'')',w)) from fixture;
select pg_temp.denied($$insert into public.supplier_internal_notes(business_id,body,created_by) values('d2000000-0000-4000-8000-000000000001','Cannot write directly',auth.uid())$$);
select pg_temp.denied($$update public.supplier_warnings set status='resolved'$$);
select pg_temp.denied($$select public.admin_supplier_workspace('d2000000-0000-4000-8000-000000000001')$$);
set local request.jwt.claims='{"sub":"d1000000-0000-4000-8000-000000000005","role":"authenticated"}';
select pg_temp.ok((public.supplier_action_list()->>'total')::int=0,'other supplier warnings hidden');
select pg_temp.ok((select count(*)=0 from public.supplier_warning_events),'other supplier events hidden');
select pg_temp.denied(format('select public.supplier_warning_respond(%L,2,''Unrelated supplier response'')',w)) from fixture;
set local request.jwt.claims='{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated"}';
select pg_temp.denied(format('select public.admin_supplier_warning_decide(%L,1,''resolved'',''Review is stale'')',w)) from fixture;
select pg_temp.denied(format('select public.admin_supplier_warning_decide(%L,2,''resolved'','''')',w)) from fixture;
select public.admin_supplier_warning_decide(w,2,'resolved','Reviewed supplier corrective response') from fixture;
select pg_temp.ok((select count(*)=3 from public.supplier_warning_events where warning_id=(select w from fixture)),'append-only issued response decision history');
select pg_temp.ok((select status='suspended' from public.account_statuses where user_id='d1000000-0000-4000-8000-000000000003'),'resolution does not reactivate account');
select pg_temp.ok((select count(*)=7 from public.admin_audit_logs where entity_id='d2000000-0000-4000-8000-000000000001' and (action like 'supplier_management.%' or action like 'supplier_warning.%' or action like 'supplier_renewal.%')),'every management mutation audited once');
select pg_temp.ok(not exists(select 1 from public.admin_audit_logs where entity_id='d2000000-0000-4000-8000-000000000001' and details::text ~ '(Private synthetic|Synthetic warning|Synthetic supplier corrected|Reviewed supplier corrective)'),'audit snapshots exclude private bodies');
set local request.jwt.claims='{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated"}';
select pg_temp.denied(format('select public.supplier_warning_respond(%L,3,''Closed warning response'')',w)) from fixture;
select pg_temp.ok(not exists(select 1 from public.notifications where body_en like '%Synthetic warning content%'),'notification bodies generic');
set local request.jwt.claims='{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated"}';
select pg_temp.denied($$select public.admin_supplier_workspace('d2000000-0000-4000-8000-000000000001')$$);
select pg_temp.denied($$select public.admin_supplier_operations_list('suppliers')$$);
select pg_temp.denied($$select public.admin_supplier_labels('d2000000-0000-4000-8000-000000000001',1,array['Denied'])$$);
select pg_temp.denied($$select public.admin_supplier_note('d2000000-0000-4000-8000-000000000001','Staff not allowed')$$);
select pg_temp.denied(format('select public.admin_supplier_archive_note(%L,''Staff not allowed'')',n)) from fixture;
select pg_temp.denied($$select public.admin_supplier_issue_warning('d2000000-0000-4000-8000-000000000001','{}')$$);
select pg_temp.denied(format('select public.admin_supplier_warning_decide(%L,3,''dismissed'',''Staff not allowed'')',w)) from fixture;
select pg_temp.denied($$select public.admin_supplier_renewal_reminder('d2000000-0000-4000-8000-000000000001')$$);
select pg_temp.ok((select count(*)=0 from public.supplier_internal_notes),'staff notes hidden');
select pg_temp.ok((select count(*)=0 from public.supplier_warnings),'staff warnings hidden');
select pg_temp.ok((select count(*)=0 from public.admin_audit_logs where action like 'supplier_management.%' or action like 'supplier_warning.%' or action like 'supplier_renewal.%'),'staff audit RLS hides operations');
select pg_temp.ok((public.admin_list('audit','{"action":"supplier_","target":"d2000000-0000-4000-8000-000000000001"}')->>'total')::int=0,'staff generic audit API hides operations');
set local request.jwt.claims='{"sub":"d1000000-0000-4000-8000-000000000004","role":"authenticated"}';
select pg_temp.denied($$select public.supplier_action_list()$$);
select pg_temp.denied($$select public.admin_supplier_operations_list('suppliers')$$);
set local role anon;set local request.jwt.claims='{}';
select pg_temp.ok(not has_function_privilege('anon','public.admin_supplier_workspace(uuid)','execute') and not has_function_privilege('anon','public.supplier_action_list(integer,integer)','execute'),'anonymous RPC privileges revoked');
reset role;
select 'Supplier management assertions passed; all synthetic records rolled back.' result;
rollback;
